"""Mitgliederliste aus der Ablage des Vereinsbüros."""

import json
from pathlib import Path


def load_members(path):
    """Mitglieder aus einer JSON-Datei; None, solange das Büro noch keine Liste abgelegt hat."""
    source = Path(path)
    if not source.exists():
        return None
    return json.loads(source.read_text(encoding="utf-8"))

touch.vendor/grouplib.py:
"""grouplib 0.3 — Einträge nach einem Schlüssel gruppieren (vendort, unverändert)."""


def _require_sequence(items):
    if isinstance(items, (str, bytes)) or not hasattr(items, "__iter__"):
        raise TypeError(f"items muss eine Folge sein, nicht {type(items).__name__}")
    return list(items)


def _key_of(entry, key):
    value = key(entry)
    if value is None:
        raise ValueError(f"kein Schlüssel für {entry!r}")
    return value


def group_by(items, key, *, sort=False):
    """Gruppiert Einträge nach key(entry), Gruppen in der Reihenfolge des Eingangs."""
    groups = {}
    for entry in _require_sequence(items):
        groups.setdefault(_key_of(entry, key), []).append(entry)
    if sort:
        return dict(sorted(groups.items()))
    return groups

