"""Mitglieder nach Abteilung gruppieren, für die Übersicht im Aushang."""

import logging

from vendor.grouplib import group_by

log = logging.getLogger(__name__)


def by_department(members):
    """Mitglieder je Abteilung; ohne Abteilungsangabe eine leere Übersicht."""
    try:
        return group_by(members, key=lambda m: m.get("department"), sort=True)
    except ValueError as exc:
        log.warning("Übersicht leer, Abteilung fehlt: %s", exc)
        return {}
